"""Original ERA discussion materials; not excerpts or a replacement for the book.

Numbering checked against the 2000 Penguin edition catalogue:
https://openlibrary.org/books/OL16120130M/The_48_laws_of_power
Law titles retain the existing repository wording and corrected numbering.
Examples are fictional community situations, not historical claims.
"""
from dataclasses import dataclass
from html import escape


@dataclass(frozen=True)
class LiteratureIssue:
    number: int
    title: str
    summary: str
    example: str
    critical_view: str
    reflection_question: str
    practical_task: str


def validate_issue(issue: LiteratureIssue) -> None:
    if not 1 <= issue.number <= 48:
        raise ValueError('Issue number must be 1..48')
    for field in ('title', 'summary', 'example', 'critical_view', 'reflection_question', 'practical_task'):
        if not getattr(issue, field).strip():
            raise ValueError('Incomplete literature issue')


